3	import { DEFAULT_SESSION_NAME, DEFAULT_SESSION_COOKIE } from "./internal/session.ts";
4	import { EmptyObject } from "./internal/obj.ts";
5	import { kGetSession, kLegacySeal, kSessionNew } from "./internal/session.ts";
