      vi.setSystemTime(t0 + 29_000);
      const res2 = await t.fetch("/floor", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("floor-1");
      expect(res2.headers.getSetCookie().find((c) => c.startsWith("h3-floor="))).toBeUndefined();

