  it("keeps loaded session data prototype-free", async () => {
    t.app.post("/proto", async (event) => {
      const session = await getSession(event, sessionConfig);
      await updateSession(event, sessionConfig, (await readBody(event)) as any);
      return {
        isAdmin: (session.data as any).isAdmin ?? null,
        inheritsObject: Object.prototype.isPrototypeOf(session.data),
      };
    });
    const seed = await t.fetch("/");
    const seedCookie = seed.headers.getSetCookie()[0].split(";")[0];
    const res = await t.fetch("/proto", {
      method: "POST",
      headers: { Cookie: seedCookie },
      body: '{"__proto__":{"isAdmin":true}}',
    });
    expect(await res.json()).toEqual({ isAdmin: null, inheritsObject: false });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("password list", () => {
    const oldPassword = "0123456789abcdef0123456789abcdef0123456789abcdef";
    const newPassword = "fedcba9876543210fedcba9876543210fedcba9876543210";
    const unknownPassword = "ffffeeeeddddccccbbbbaaaa99998888777766665555444";

    const oldConfig: SessionConfig = { name: "h3-rot", password: oldPassword };
    const rotatedConfig: SessionConfig = { name: "h3-rot", password: [newPassword, oldPassword] };
    const unknownConfig: SessionConfig = { name: "h3-rot", password: unknownPassword };

    const sessionCookie = (res: Response) => res.headers.getSetCookie()[0].split(";")[0];

    const mountSessionRoute = (path: string, config: SessionConfig) =>
      t.app.all(path, async (event) => {
        const session = await useSession(event, config);
        if (event.req.method === "POST") {
          await session.update((await readBody(event)) as any);
        }
        return { id: session.id, data: session.data };
      });

    beforeEach(() => {
      mountSessionRoute("/rot/old", oldConfig);
      mountSessionRoute("/rot/rotated", rotatedConfig);
      mountSessionRoute("/rot/unknown", unknownConfig);
    });

    it("opens a session sealed with an older password", async () => {
      const created = await t.fetch("/rot/old", {
        method: "POST",
        body: JSON.stringify({ user: "alice" }),
      });
      const cookie = sessionCookie(created);
      const before = await created.json();

      const res = await t.fetch("/rot/rotated", { headers: { Cookie: cookie } });
      expect(await res.json()).toMatchObject({ id: before.id, data: { user: "alice" } });
    });

    it("seals with the first password only", async () => {
      const res = await t.fetch("/rot/rotated", {
        method: "POST",
        body: JSON.stringify({ user: "bob" }),
      });
      const sealed = decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-rot=([^;]+)/)![1]);

      expect(await unseal(sealed, newPassword, sealDefaults)).toMatchObject({
        data: { user: "bob" },
      });
      await expect(unseal(sealed, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("starts a new session for a password outside the list", async () => {
      const foreign = await t.fetch("/rot/unknown", {
        method: "POST",
        body: JSON.stringify({ user: "mallory" }),
      });
      const cookie = sessionCookie(foreign);
      const before = await foreign.json();

      const res = await t.fetch("/rot/rotated", { headers: { Cookie: cookie } });
      const body = await res.json();
      expect(body.id).not.toBe(before.id);
      expect(body.data).toEqual({});
    });

    it("reports an empty password list as a configuration error", async () => {
      const emptyConfig: SessionConfig = { name: "h3-rot", password: [] };
      t.app.get("/rot/empty-use", async (event) => {
        await useSession(event, emptyConfig);
        return "ok";
      });
      t.app.get("/rot/empty-get", async (event) => {
        await getSession(event, emptyConfig);
        return "ok";
      });

      await t.fetch("/rot/empty-use");
      expect(t.errors[0].message).toContain("empty");
      t.errors = [];

      await t.fetch("/rot/empty-get");
      expect(t.errors[0].message).toContain("empty");
      t.errors = [];
    });
  });
});

